                            Gui.label(
                                rowctx,
                                list,
                                "No matching options",
                                { Size = UDim2.new(1, 0, 0, 32), TextXAlignment = Enum.TextXAlignment.Center },
                                "TextMuted"
                            )
                        )
                    end
                    for index, value in ipairs(filtered) do
                        local selected = options.Multi and table.find(self:GetValue(), value) ~= nil
                            or self:GetValue() == value
