        )
    end
    local rendering = false
    local function normalize(value)
        if kind == "Number" then
            if not Math.finite(value) then
                return nil
            end
            if options.Min and value < options.Min then
                return nil
            end
            if options.Max and value > options.Max then
                return nil
            end
