__modules["Aurelis/Core/Motion"] = function(__require)
--!nonstrict
local TweenService = game:GetService("TweenService")
local Motion = {}
Motion.__index = Motion
local presets = {
    Instant = { 0, Enum.EasingStyle.Linear },
    Fast = { 0.12, Enum.EasingStyle.Quad },
    Normal = { 0.19, Enum.EasingStyle.Quart },
    Slow = { 0.26, Enum.EasingStyle.Quart },
    Spring = { 0.24, Enum.EasingStyle.Back },
}
function Motion.new()
    return setmetatable({ Speed = 1, _active = {}, ActiveCount = 0 }, Motion)
end
function Motion:_remove(object, entry, cancel)
    local bucket = self._active[object]
    if not bucket or not bucket[entry] then
        return
    end
    bucket[entry] = nil
    if next(bucket) == nil then
        self._active[object] = nil
    end
    self.ActiveCount -= 1
    entry.Connection:Disconnect()
    if cancel then
        entry.Tween:Cancel()
    end
end
function Motion:Cancel(object)
    local bucket = self._active[object]
    if not bucket then
        return
    end
    local entries = {}
    for entry in pairs(bucket) do
        table.insert(entries, entry)
    end
    for _, entry in ipairs(entries) do
        self:_remove(object, entry, true)
    end
end
function Motion:Tween(object, properties, preset)
    local bucket = self._active[object]
    if bucket then
        local conflicts = {}
        for entry in pairs(bucket) do
            for property in pairs(properties) do
                if entry.Properties[property] ~= nil then
                    table.insert(conflicts, entry)
                    break
                end
            end
        end
        for _, entry in ipairs(conflicts) do
            self:_remove(object, entry, true)
        end
    end
    local settings = presets[preset or "Normal"] or presets.Normal
    if self.Speed <= 0 or settings[1] == 0 then
        for key, value in pairs(properties) do
            object[key] = value
        end
        return nil
    end
    local tween = TweenService:Create(
        object,
        TweenInfo.new(settings[1] / math.max(self.Speed, 0.05), settings[2], Enum.EasingDirection.Out),
        properties
    )
    local entry = { Tween = tween, Properties = properties }
    entry.Connection = tween.Completed:Connect(function()
        self:_remove(object, entry, false)
    end)
    self._active[object] = self._active[object] or {}
    self._active[object][entry] = true
    self.ActiveCount += 1
    tween:Play()
    return tween
end
function Motion:Destroy()
    local objects = {}
    for object in pairs(self._active) do
        table.insert(objects, object)
    end
    for _, object in ipairs(objects) do
        self:Cancel(object)
    end
end
return Motion

end
__modules["Aurelis/Core/Responsive"] = function(__require)
--!strict
local Responsive = {}
function Responsive.breakpoint(width)
    return width >= 700 and "Desktop" or (width >= 500 and "Compact" or "Mobile")
end
function Responsive.initialSize(preferred, viewport, minimum)
    -- Leave room around a floating window, including on short landscape phone screens.
    if viewport.X < 1 or viewport.Y < 1 then
        return preferred
    end
    return Vector2.new(
        math.min(preferred.X, math.max(minimum.X, math.floor(viewport.X * 0.82))),
        math.min(preferred.Y, math.max(minimum.Y, math.floor(viewport.Y * 0.82)))
    )
end
function Responsive.geometry(position, size, viewport, minimum)
    local maximum = Vector2.new(math.max(1, viewport.X - 16), math.max(1, viewport.Y - 16))
    local actual = Vector2.new(
        math.clamp(size.X, math.min(minimum.X, maximum.X), maximum.X),
        math.clamp(size.Y, math.min(minimum.Y, maximum.Y), maximum.Y)
    )
    return Vector2.new(
        math.clamp(position.X, 8, math.max(8, viewport.X - actual.X - 8)),
        math.clamp(position.Y, 8, math.max(8, viewport.Y - actual.Y - 8))
    ),
        actual
end
return Responsive

end
__modules["Aurelis/Core/State"] = function(__require)
--!nonstrict
local Signal = __require("Aurelis/Utility/Signal")
local Table = __require("Aurelis/Utility/Table")
local State = {}
State.__index = State
local collecting = nil

function State.new(value)
    return setmetatable({ _value = Table.copy(value), Changed = Signal.new(), _dead = false }, State)
end
function State:Get()
    if collecting then
        collecting[self] = true
    end
    return Table.copy(self._value)
end
function State:Set(value)
    assert(not self._dead, "State is destroyed")
    assert(not self._compute, "Computed state is read-only")
    if Table.equal(value, self._value) then
        return
    end
    self._value = Table.copy(value)
    self.Changed:Fire(self:Get())
end
function State:Subscribe(callback, immediate)
    local connection = self.Changed:Connect(callback)
    if immediate ~= false then
        callback(self:Get())
    end
    return connection
end
function State:Destroy()
    if self._dead then
        return
    end
    self._dead = true
    if self._subscriptions then
        for _, connection in ipairs(self._subscriptions) do
            connection:Disconnect()
        end
    end
    self.Changed:Destroy()
end
function State.computed(callback)
    local state = State.new(nil)
    state._compute, state._subscriptions = callback, {}
    local running = false
    local function evaluate()
        assert(not running, "Computed state cycle")
        running = true
        local parentCollector, dependencies = collecting, {}
        collecting = dependencies
        local ok, value = pcall(callback)
        collecting, running = parentCollector, false
        if not ok then
            error(value, 2)
        end
        for _, connection in ipairs(state._subscriptions) do
            connection:Disconnect()
        end
        table.clear(state._subscriptions)
        for dependency in pairs(dependencies) do
            assert(dependency ~= state, "Computed state cannot depend on itself")
            table.insert(state._subscriptions, dependency.Changed:Connect(evaluate))
        end
        if not Table.equal(value, state._value) then
            state._value = Table.copy(value)
            state.Changed:Fire(state:Get())
        end
    end
    evaluate()
    return state
end
return State

end
