            if input.UserInputType == Enum.UserInputType.Touch then
                return
            end
            local screen = app.Root.AbsoluteSize
            if position.Y < 16 then
                self:Maximize()
            elseif position.X < 16 then
                self:Snap("Left")
            elseif position.X > screen.X - 16 then
                self:Snap("Right")
            end
        end)
    end))
