        if not self.Maximized then
            self._size =
                Responsive.initialSize(self._size, app.Root.AbsoluteSize / self.Scale, self.MinimumSize)
        end
        self:_geometry()
    end))
    self.Maid:Give(self.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
