    local job = Automation:AddCard({
        Title = "Workspace task",
        Description = "A finite simulated task to demonstrate progress and cancellation.",
        Icon = "play",
    })
    local progress = job:AddProgress({ Title = "Progress", Default = 0 })
    local jobStatus = Aurelis.State("Stopped")
    Window.Maid:Give(jobStatus)
    job:AddLabel({ Title = "Status", Value = "Stopped", Status = true }):Bind(jobStatus)
    local pending, running = nil, false
    local function stop()
        running = false
        if pending then
            pcall(task.cancel, pending)
            pending = nil
        end
        if not Window.Destroyed then
            jobStatus:Set("Stopped")
        end
    end
    local function tick()
        pending = nil
        if not running or Window.Destroyed then
            return
        end
        local nextValue = math.min(1, progress:GetValue() + 0.05)
        progress:SetValue(nextValue)
        if nextValue >= 1 then
            running = false
            jobStatus:Set("Complete")
            notify("Task complete", "Workspace task finished.", "Success")
        else
            pending = task.delay(0.25, tick)
        end
    end
    Window.Maid:Give(stop)
    job:AddButton({
        Title = "Start task",
        Text = "Start",
        Variant = "Primary",
        Icon = "play",
        Callback = function()
            stop()
            running = true
            progress:SetValue(0)
            jobStatus:Set("Running")
            tick()
        end,
    })
    job:AddButton({ Title = "Stop task", Text = "Stop", Icon = "stop", Callback = stop })
    local utility = Utilities:AddSection({
        Title = "Interaction lab",
        Description = "Right-click a row or hold it on touch to open its context menu.",
        Collapsible = true,
    })
    utility:AddButton({
        Title = "Save snapshot",
        Description = "Save current flags using the configured storage adapter.",
        Icon = "save",
        Tooltip = "The default adapter stores configs for this app session.",
        Callback = function()
            local ok, err = Aurelis.Config:Save("Default")
            notify(
                ok and "Configuration saved" or "Save failed",
                ok and "Default is ready to load." or tostring(err),
                ok and "Success" or "Error"
            )
        end,
    })
    utility:AddButton({
        Title = "Confirmation",
        Text = "Open dialog",
        Callback = function()
            Aurelis:Dialog({
                Title = "Apply workspace changes?",
                Content = "Your current workspace settings will remain available in flags.",
                OnConfirm = function()
                    notify("Applied", "Workspace confirmed.", "Success")
                end,
            }, Window)
        end,
    })
    utility:AddButton({
        Title = "Input dialog",
        Text = "Rename workspace",
        Callback = function()
            Aurelis:Dialog({
                Title = "Workspace name",
                Kind = "Input",
                Default = Window.Subtitle.Text,
                Validate = function(value)
                    return #value >= 2, "Use at least two characters"
                end,
                OnConfirm = function(value)
                    Window.Subtitle.Text = value
                end,
            }, Window)
        end,
    })
    utility:AddButton({
        Title = "Destructive dialog",
        Text = "Clear history",
        Variant = "Danger",
        Callback = function()
            Aurelis:Dialog({
                Title = "Clear notification history?",
                Content = "Current history entries will be removed.",
                Kind = "Destructive",
                ConfirmText = "Clear",
                OnConfirm = function()
                    Aurelis.NotificationCenter:Clear()
                end,
            }, Window)
        end,
    })
    utility:AddInput({
        Title = "Numeric input",
        Type = "Number",
        Default = 5,
        Min = 1,
        Max = 60,
        Live = true,
        Flag = "utilities.interval",
        Tooltip = "Only numbers from 1 to 60 are accepted.",
    })
    utility:AddInput({
        Title = "Masked input",
        Type = "Password",
        Placeholder = "Local demo text",
        CharacterLimit = 48,
    })
    local load = Utilities:AddCard({ Title = "Skeleton preview", Icon = "layers" })
    load:AddMetric({ Label = "State", Value = "Loaded" })
    load:AddMetric({ Label = "Assets", Value = "Embedded vectors" })
    utility:AddToggle({
        Title = "Show skeleton",
        Default = false,
        Callback = function(value)
            load:SetLoading(value)
        end,
    })
    local monitor = Developer:AddCard({ Title = "UI performance", Icon = "cpu" })
    local fps = monitor:AddMetric({ Label = "FPS", Value = "Monitor inactive" })
    local instanceCount = monitor:AddMetric({ Label = "UI instances", Value = "—" })
    local connections = monitor:AddMetric({ Label = "Connections", Value = "—" })
    monitor:AddToggle({
        Title = "Developer overlay",
        Default = false,
        Callback = function(value)
            Aurelis:SetDeveloperOverlay(value)
        end,
    })
    local inspector = Developer:AddSection({ Title = "State & flags", Collapsible = true })
    local stateRow = inspector:AddLabel({ Title = "Session state", Value = "" }):Bind(Status)
    local flagCount = inspector:AddLabel({ Title = "Registered flags", Value = "0" })
    local changedFlag = inspector:AddLabel({ Title = "Last changed", Value = "None" })
    local function updateFlags(key, value)
        local count = 0
        for _ in pairs(Aurelis.FlagStore:Snapshot()) do
            count += 1
        end
        flagCount:SetValue(tostring(count))
        if key then
            changedFlag:SetValue(key .. " = " .. tostring(value))
        end
    end
    Window.Maid:Give(Aurelis.FlagStore.Changed:Connect(updateFlags))
    inspector:AddButton({
        Title = "Inspect flags",
        Text = "Open snapshot",
        Callback = function()
            Aurelis:Dialog({
                Title = "Flag snapshot",
                Kind = "Input",
                Default = Aurelis.Config:Export(),
                ConfirmText = "Done",
                Content = "Serialized current state. Use your platform's text selection to copy it.",
            }, Window)
        end,
    })
    local notificationTest = Developer:AddSection({ Title = "Notification testing" })
    for _, kind in ipairs({ "Info", "Success", "Warning", "Error" }) do
        notificationTest:AddButton({
            Title = kind,
            Text = "Send " .. kind,
            Callback = function()
                notify(kind .. " notification", "A notification generated by the showcase.", kind)
            end,
        })
    end
    local performanceConnection = nil
    Window.Maid:Give(Window.PageChanged:Connect(function(page)
        if performanceConnection then
            performanceConnection:Disconnect()
            performanceConnection = nil
        end
        if page == Developer then
            performanceConnection = Aurelis.Performance:Acquire(function(values)
                fps:SetValue(tostring(values.FPS))
                instanceCount:SetValue(tostring(values.Instances))
                connections:SetValue(tostring(values.Connections))
                Window.StatusBar:Set({ FPS = values.FPS })
            end)
        end
    end))
    Window.Maid:Give(function()
        if performanceConnection then
            performanceConnection:Disconnect()
        end
    end)
    local theme = Settings:AddSection({
        Title = "Theme editor",
        Description = "Changes apply live without rebuilding the interface.",
        Icon = "palette",
        Collapsible = true,
    })
    theme:AddDropdown({
        Title = "Theme",
        Values = { "Eclipse", "Obsidian", "Graphite", "Tokyo", "OLED", "Frost", "Light" },
        Default = "Eclipse",
        Flag = "settings.theme",
        ConfigPriority = -100,
        Callback = function(value)
            Aurelis:SetTheme(value)
        end,
    })
    local themeControls = {}
    for _, token in ipairs({ "Accent", "Background", "Surface", "Border", "TextPrimary" }) do
        themeControls[token] = theme:AddColorPicker({
            Title = token == "TextPrimary" and "Text" or token,
            Default = Window.Theme.Tokens[token],
            Flag = "theme." .. token,
            Callback = function(value)
                Window:SetTheme({ [token] = value })
            end,
        })
    end
    themeControls.Radius = theme:AddSlider({
        Title = "Corner radius",
        Min = 0,
        Max = 24,
        Increment = 1,
        Default = 12,
        Flag = "theme.radius",
        Callback = function(value)
            Window:SetTheme({ Radius = value })
        end,
    })
    themeControls.Transparency = theme:AddSlider({
        Title = "Transparency",
        Min = 0,
        Max = 0.65,
        Increment = 0.01,
        Default = 0.02,
        Flag = "theme.transparency",
        Callback = function(value)
            Window:SetTheme({ Transparency = value })
        end,
    })
    themeControls.AnimationSpeed = theme:AddSlider({
        Title = "Animation speed",
        Min = 0,
        Max = 3,
        Increment = 0.1,
        Default = 1,
        Suffix = "×",
        Flag = "theme.motion",
        Callback = function(value)
            Window:SetTheme({ AnimationSpeed = value })
        end,
    })
    Window.Maid:Give(Window.Theme.Changed:Connect(function(tokens)
        for token, control in pairs(themeControls) do
            control:SetValue(tokens[token], true)
        end
        visualAccent:SetValue(tokens.Accent, true)
    end))
    theme:AddSlider({
        Title = "UI scale",
        Min = 0.65,
        Max = 1.5,
        Increment = 0.05,
        Default = 1,
        Flag = "settings.scale",
        Callback = function(value)
            Window:SetScale(value)
        end,
    })
    theme:AddKeybind({
        Title = "Menu key",
        Default = Enum.KeyCode.RightShift,
        Mode = "Toggle",
        Flag = "settings.menuKey",
    })
    Window.Maid:Give(Aurelis.FlagStore.Changed:Connect(function(key, value)
        if key == "settings.menuKey" then
            Window.ToggleKey = value.Key
        end
    end))
    local configs = Settings:AddSection({
        Title = "Configurations",
        Description = "Session storage by default. Inject a persistent adapter for cross-session saving.",
        Icon = "save",
        Collapsible = true,
    })
    local configName = "Default"
    configs:AddInput({
        Title = "Name",
        Default = "Default",
        Live = true,
        CharacterLimit = 64,
        Validate = function(value)
            return #value > 0 and string.match(value, "^[%w _%-]+$") ~= nil,
                "Use letters, digits, spaces, _ or -"
        end,
        Callback = function(value)
            configName = value
        end,
    })
    local configList = configs:AddDropdown({
        Title = "Saved configurations",
        Values = {},
        Default = "",
        Callback = function(value)
            if value ~= "" then
                configName = value
            end
        end,
    })
    local refreshConfigs
    local empty = configs:AddEmptyState({
        Title = "No configurations yet",
        Icon = "save",
        Description = "Create a configuration to save your current interface settings.",
        Action = {
            Title = "Create configuration",
            Callback = function()
                local ok, err = Aurelis.Config:Save(configName)
                if ok then
                    refreshConfigs()
                else
                    notify("Save failed", tostring(err), "Error")
                end
            end,
        },
    })
    refreshConfigs = function()
        local names = Aurelis.Config:List()
        configList:SetValues(names)
        empty:SetVisible(#names == 0)
    end
    configs:AddButton({
        Title = "Save",
        Icon = "save",
        Variant = "Primary",
        Callback = function()
            local ok, err = Aurelis.Config:Save(configName)
            refreshConfigs()
            notify(ok and "Configuration saved" or "Save failed", tostring(err), ok and "Success" or "Error")
        end,
    })
    configs:AddButton({
        Title = "Load",
        Icon = "download",
        Callback = function()
            local ok, result = Aurelis.Config:Load(configName)
            notify(
                ok and "Configuration loaded" or "Load failed",
                ok and tostring(#result.Applied) .. " flags applied" or tostring(result),
                ok and "Success" or "Error"
            )
        end,
    })
    configs:AddButton({
        Title = "Rename",
        Icon = "edit",
        Callback = function()
            Aurelis:Dialog({
                Title = "Rename configuration",
                Kind = "Input",
                Default = configName,
                OnConfirm = function(value)
                    local ok, err = Aurelis.Config:Rename(configName, value)
                    if ok then
                        configName = value
                        refreshConfigs()
                    else
                        notify("Rename failed", tostring(err), "Error")
                    end
                end,
            }, Window)
        end,
    })
    configs:AddButton({
        Title = "Delete",
        Icon = "trash",
        Variant = "Danger",
        Callback = function()
            Aurelis:Dialog({
                Title = "Delete " .. configName .. "?",
                Kind = "Destructive",
                OnConfirm = function()
                    local ok, err = Aurelis.Config:Delete(configName)
                    refreshConfigs()
                    if not ok then
                        notify("Delete failed", tostring(err), "Error")
                    end
                end,
            }, Window)
        end,
    })
    local commands = {
        {
            "Open Dashboard",
            function()
                Dashboard:Select()
            end,
        },
        {
            "Open Player",
            function()
                movement:Select()
            end,
        },
        {
            "Open Settings",
            function()
                Settings:Select()
            end,
        },
        {
            "Change Theme",
            function()
                Window:SetTheme(Window.Theme.Name == "Light" and "Eclipse" or "Light")
            end,
        },
        {
            "Save Configuration",
            function()
                Aurelis.Config:Save(configName)
                refreshConfigs()
            end,
        },
        {
            "Restore Window",
            function()
                Window:Restore()
            end,
        },
    }
    for _, command in ipairs(commands) do
        Window.Maid:Give(
            Aurelis.Commands:Register({ Name = command[1], Keywords = { "workspace" }, Callback = command[2] })
        )
    end
    refreshConfigs()
    updateFlags()
    Dashboard:Select()
    notify("Interface initialized", "Welcome to AURELIS. Press Ctrl + K to explore.", "Success")
    return Window
end
return Showcase

end
__modules["Aurelis/Navigation/Breadcrumb"] = function(__require)
--!nonstrict
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local Breadcrumb = {}
Breadcrumb.__index = Breadcrumb
function Breadcrumb.new(window, host)
    return setmetatable(
        { Window = window, App = window.App, Theme = window.Theme, Maid = Cleanup.new(), Host = host },
        Breadcrumb
    )
end
function Breadcrumb:Set(page)
    self.Maid:Destroy()
    self.Maid = Cleanup.new()
    local chain = {}
    local current = page
    while current do
        table.insert(chain, 1, current)
        current = current.Parent
    end
    local layout = Gui.new(self, "UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Center,
    }, nil, self.Host)
    self.Maid:Give(layout)
    for index, item in ipairs(chain) do
        if index > 1 then
            self.Maid:Give(
                Gui.label(
                    self,
                    self.Host,
                    "/",
                    { Size = UDim2.fromOffset(8, 22), LayoutOrder = index * 2 - 1, TextSize = 10 },
                    "TextMuted"
                )
            )
        end
        local width = game:GetService("TextService")
            :GetTextSize(item.Title, 10, Enum.Font.Gotham, Vector2.new(1000, 22)).X + 8
        local button = Gui.button(
            self,
            self.Host,
            item.Title,
            { Size = UDim2.fromOffset(width, 24), LayoutOrder = index * 2, TextSize = 10 }
        )
        self.Maid:Give(button)
        self.Maid:Give(button.Activated:Connect(function()
            self.Window:SelectTab(item)
        end))
    end
end
function Breadcrumb:Destroy()
    self.Maid:Destroy()
end
return Breadcrumb

end
__modules["Aurelis/Navigation/Container"] = function(__require)
--!nonstrict
-- Requires are deliberately lazy: cards and sections can themselves contain components.
local Container = {}
function Container.attach(target)
    target.Components = {}
    for name, method in pairs(Container) do
        if name ~= "attach" then
            target[name] = method
        end
    end
    return target
end
local factories = {
    AddButton = function()
        return __require("Aurelis/Components/Button")
    end,
    AddToggle = function()
        return __require("Aurelis/Components/Toggle")
    end,
    AddSlider = function()
        return __require("Aurelis/Components/Slider")
    end,
    AddRangeSlider = function()
        return __require("Aurelis/Components/RangeSlider")
    end,
    AddDropdown = function()
        return __require("Aurelis/Components/Dropdown")
    end,
    AddInput = function()
        return __require("Aurelis/Components/Input")
    end,
    AddKeybind = function()
        return __require("Aurelis/Components/Keybind")
    end,
    AddColorPicker = function()
        return __require("Aurelis/Components/ColorPicker")
    end,
    AddSegmented = function()
        return __require("Aurelis/Components/Segmented")
    end,
    AddProgress = function()
        return __require("Aurelis/Components/Progress")
    end,
    AddLabel = function()
        return __require("Aurelis/Components/Label")
    end,
    AddChart = function()
        return __require("Aurelis/Components/Chart")
    end,
    AddEmptyState = function()
        return __require("Aurelis/Components/EmptyState")
    end,
    AddCard = function()
        return __require("Aurelis/Components/Card")
    end,
    AddSection = function()
        return __require("Aurelis/Navigation/Section")
    end,
}
for name, load in pairs(factories) do
    Container[name] = function(self, options)
        local count = #self.Components
        local ok, result = pcall(function()
            return load().new(self, options or {})
        end)
        if not ok then
            -- Constructor errors must not leave a half-created row or flag behind.
            for index = #self.Components, count + 1, -1 do
                self.Components[index]:Destroy()
            end
            error(result, 2)
        end
        return result
    end
end
function Container:DestroyChildren()
    local children = table.clone(self.Components)
    for _, component in ipairs(children) do
        component:Destroy()
    end
end
return Container

end
__modules["Aurelis/Navigation/Page"] = function(__require)
--!nonstrict
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local Container = __require("Aurelis/Navigation/Container")
local Table = __require("Aurelis/Utility/Table")
local Page = {}
Page.__index = Page
function Page.new(window, options, parent)
    local self = setmetatable({
        App = window.App,
        Window = window,
        Theme = window.Theme,
        Maid = Cleanup.new(),
        Title = options.Title or "Page",
        Id = options.Id or options.Title,
        Icon = options.Icon or "folder",
        Parent = parent,
        Pages = {},
        Destroyed = false,
        Options = options,
    }, Page)
    self.Page = self
    Container.attach(self)
    self.Root = Gui.new(
        self,
        "CanvasGroup",
        { Name = self.Title, Size = UDim2.fromScale(1, 1), Visible = false, GroupTransparency = 0 },
        nil,
        window.ContentHost
    )
    self.Maid:Give(self.Root)
    self.Scroller = Gui.new(self, "ScrollingFrame", {
        Size = UDim2.fromScale(1, 1),
        CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        ScrollBarThickness = 3,
        BorderSizePixel = 0,
    }, { ScrollBarImageColor3 = "BorderStrong" }, self.Root)
    Gui.padding(self, self.Scroller, 2)
    self.Content = Gui.new(
        self,
        "Frame",
        { Size = UDim2.new(1, -8, 0, 0), AutomaticSize = Enum.AutomaticSize.Y },
        nil,
        self.Scroller
    )
    Gui.list(self, self.Content, 12)
    self.Maid:Give(function()
        self:DestroyChildren()
        for _, page in ipairs(table.clone(self.Pages)) do
            page:Destroy()
        end
        if parent then
            Table.removeValue(parent.Pages, self)
        else
            Table.removeValue(window.Tabs, self)
        end
        window.Sidebar:Remove(self)
        if window.SelectedPage == self then
            window.SelectedPage = nil
        end
    end)
    self.Maid:Give(self.Root.Destroying:Connect(function()
        self:Destroy()
    end))
    return self
end
function Page:AddPage(options)
    options = options or {}
    self.App.Icons:Get(options.Icon or "folder")
    local page = Page.new(self.Window, options, self)
    table.insert(self.Pages, page)
    self.Window.Sidebar:Add(page)
    return page
end
function Page:Select()
    self.Window:SelectTab(self)
    return self
end
function Page:SetBadge(value)
    self.Options.Badge = value
    self.Window.Sidebar:Refresh()
    return self
end
function Page:Destroy()
    if self.Destroyed then
        return
    end
    self.Destroyed = true
    self.Maid:Destroy()
end
return Page

end
__modules["Aurelis/Navigation/Section"] = function(__require)
--!nonstrict
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local Icons = __require("Aurelis/Utility/Icons")
local Table = __require("Aurelis/Utility/Table")
local Container = __require("Aurelis/Navigation/Container")
local Section = {}
Section.__index = Section
function Section.new(owner, options)
    local self = setmetatable({
        App = owner.App,
        Window = owner.Window,
        Theme = owner.Theme,
        Maid = Cleanup.new(),
        Owner = owner,
        Page = owner.Page or owner,
        Title = options.Title or "Section",
        Collapsed = options.Collapsed == true,
        Collapsible = options.Collapsible == true,
        Destroyed = false,
    }, Section)
    Container.attach(self)
    owner._nextOrder = (owner._nextOrder or 0) + 1
    self.Root = Gui.new(self, "Frame", {
        Name = "Section",
        Size = UDim2.new(1, 0, 0, 60),
        ClipsDescendants = true,
        BackgroundTransparency = 0,
        LayoutOrder = owner._nextOrder,
    }, { BackgroundColor3 = "Surface" }, owner.Content)
    self.Maid:Give(self.Root)
    Gui.corner(self, self.Root)
    Gui.stroke(self, self.Root)
    table.insert(owner.Components, self)
    self.Maid:Give(function()
        self:DestroyChildren()
        Table.removeValue(owner.Components, self)
    end)
    local headerHeight = options.Description and 60 or 44
    self.Header = Gui.new(self, "TextButton", { Size = UDim2.new(1, 0, 0, headerHeight) }, nil, self.Root)
    if options.Icon then
        Icons:Create(self, self.Header, options.Icon, { Position = UDim2.fromOffset(14, 13) })
    end
    Gui.label(self, self.Header, self.Title, {
        Position = UDim2.fromOffset(options.Icon and 42 or 14, 12),
        Size = UDim2.new(1, -64, 0, 20),
        Font = Enum.Font.GothamMedium,
        TextTruncate = Enum.TextTruncate.AtEnd,
    })
    if options.Description then
        Gui.label(self, self.Header, options.Description, {
            Position = UDim2.fromOffset(14, 35),
            Size = UDim2.new(1, -28, 0, 18),
            TextSize = 11,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, "TextMuted")
    end
    local chevron = nil
    if self.Collapsible then
        chevron = Icons:Create(
            self,
            self.Header,
            "chevron-down",
            { Position = UDim2.new(1, -30, 0, 16), Size = UDim2.fromOffset(12, 12) }
        )
    end
    self.Content = Gui.new(
        self,
        "Frame",
        { Position = UDim2.fromOffset(8, headerHeight), Size = UDim2.new(1, -16, 0, 0) },
        nil,
        self.Root
    )
    local layout = Gui.list(self, self.Content, 3)
    local function resize(animate)
        if self.Destroyed then
            return
        end
        local height = layout.AbsoluteContentSize.Y / self.Window.Scale
        self.Content.Size = UDim2.new(1, -16, 0, height)
        local size = UDim2.new(1, 0, 0, headerHeight + (self.Collapsed and 0 or height + 10))
        if animate then
            self.App.Motion:Tween(self.Root, { Size = size }, "Normal")
        else
            self.Root.Size = size
        end
    end
    self._resize = resize
    self.Maid:Give(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        resize(false)
    end))
    self.Maid:Give(self.Header.Activated:Connect(function()
        if self.Collapsible then
            self:SetCollapsed(not self.Collapsed)
        end
    end))
    self.Maid:Give(self.Root.Destroying:Connect(function()
        self:Destroy()
    end))
    self.Chevron = chevron
    self.HeaderHeight = headerHeight
    resize(false)
    return self
end
function Section:SetCollapsed(collapsed)
    self.Collapsed = collapsed == true
    if self.Chevron then
        self.App.Motion:Tween(self.Chevron, { Rotation = self.Collapsed and -90 or 0 }, "Normal")
    end
    self._resize(true)
    return self
end
function Section:SetVisible(visible)
    self.Root.Visible = visible == true
    return self
end
function Section:Destroy()
    if self.Destroyed then
        return
    end
    self.Destroyed = true
    self.Maid:Destroy()
end
return Section

end
__modules["Aurelis/Navigation/Sidebar"] = function(__require)
