__modules["Aurelis/Overlay/CommandPalette"] = function(__require)
--!nonstrict
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local Palette = {}
Palette.__index = Palette
function Palette.new(app)
    return setmetatable({ App = app }, Palette)
end
function Palette:Open(window, provider, title)
    local selected, results, render = 1, {}, nil
    local function activate()
        local entry = results[selected]
        if entry then
            self.App.Overlay:Close("Selected")
            self.App:Call(entry.Callback)
        end
    end
    self.App.Overlay:Open(window, nil, Vector2.new(510, 360), function(ctx, panel)
        local field = Gui.new(ctx, "TextBox", {
            Position = UDim2.fromOffset(18, 12),
            Size = UDim2.new(1, -36, 0, 38),
            ClearTextOnFocus = false,
            PlaceholderText = title or "Search commands…",
            TextSize = 15,
        }, { TextColor3 = "TextPrimary", PlaceholderColor3 = "TextMuted" }, panel)
        Gui.label(
            ctx,
            panel,
            "↑ ↓  navigate      ENTER  select      ESC  close",
            { Position = UDim2.new(0, 18, 1, -27), Size = UDim2.new(1, -36, 0, 20), TextSize = 9 },
            "TextMuted"
        )
        local list = Gui.new(ctx, "ScrollingFrame", {
            Position = UDim2.fromOffset(8, 60),
            Size = UDim2.new(1, -16, 1, -94),
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 3,
        }, { ScrollBarImageColor3 = "BorderStrong" }, panel)
        Gui.list(ctx, list, 3)
        local rows = nil
        render = function(requery)
            if rows then
                ctx.Maid:Remove(rows)
            end
            rows = Cleanup.new()
            ctx.Maid:Give(rows)
            local rowctx = { App = ctx.App, Theme = ctx.Theme, Maid = rows }
            if requery then
                results = provider(field.Text)
                selected = 1
            end
            selected = math.clamp(selected, 1, math.max(1, #results))
            if #results == 0 then
                rows:Give(
                    Gui.label(
                        rowctx,
                        list,
                        "No results found",
                        { Size = UDim2.new(1, 0, 0, 90), TextXAlignment = Enum.TextXAlignment.Center },
                        "TextMuted"
                    )
                )
            end
            for index, entry in ipairs(results) do
                if index > 100 then
                    break
                end
                local button = Gui.button(rowctx, list, "", {
                    Size = UDim2.new(1, -2, 0, entry.Path and 54 or 38),
                    LayoutOrder = index,
                    BackgroundTransparency = index == selected and 0.1 or 1,
                })
                rows:Give(button)
                Gui.label(rowctx, button, entry.Name, {
                    Position = UDim2.fromOffset(12, 8),
                    Size = UDim2.new(1, -24, 0, 22),
                    TextTruncate = Enum.TextTruncate.AtEnd,
                })
                if entry.Path then
                    Gui.label(rowctx, button, entry.Path, {
                        Position = UDim2.fromOffset(12, 29),
                        Size = UDim2.new(1, -24, 0, 18),
                        TextSize = 10,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                    }, "TextMuted")
                end
                rows:Give(button.Activated:Connect(function()
                    selected = index
                    activate()
                end))
            end
            local rowHeight = results[selected] and results[selected].Path and 57 or 41
            list.CanvasPosition =
                Vector2.new(0, math.max(0, (selected - 1) * rowHeight - list.AbsoluteSize.Y + rowHeight))
        end
        ctx.Maid:Give(field:GetPropertyChangedSignal("Text"):Connect(function()
            render(true)
        end))
        render(true)
        field:CaptureFocus()
    end, {
        Centered = true,
        OnInput = function(input)
            if input.KeyCode == Enum.KeyCode.Up or input.KeyCode == Enum.KeyCode.Down then
                selected = math.clamp(
                    selected + (input.KeyCode == Enum.KeyCode.Down and 1 or -1),
                    1,
                    math.min(100, math.max(1, #results))
                )
                if render then
                    render(false)
                end
                return true
            elseif input.KeyCode == Enum.KeyCode.Return then
                activate()
                return true
            end
        end,
    })
end
return Palette

end
__modules["Aurelis/Overlay/ContextMenu"] = function(__require)
--!nonstrict
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local ContextMenu = {}
ContextMenu.__index = ContextMenu
function ContextMenu.new(app)
    return setmetatable({ App = app, Registry = {}, Maid = Cleanup.new(), Pending = nil }, ContextMenu)
end
function ContextMenu:_cancel()
    if self.Pending then
        pcall(task.cancel, self.Pending)
        self.Pending = nil
    end
    self.Touch = nil
end
function ContextMenu:Start()
    local function find(point)
        for index = #self.App.Windows, 1, -1 do
            local window = self.App.Windows[index]
            if window.Visible and self.App.Input:Contains(window.Root, point) then
                for owner in pairs(self.Registry) do
                    if
                        owner.Window == window
                        and not owner.Destroyed
                        and self.App.Input:Contains(owner.Root, point)
                    then
                        return owner
                    end
                end
                return nil
            end
        end
    end
    self.Maid:Give(self.App.Input:OnBegan(function(input)
        local right = input.UserInputType == Enum.UserInputType.MouseButton2
        local touch = input.UserInputType == Enum.UserInputType.Touch
        if not right and not touch then
            return
        end
        self:_cancel()
        local point = self.App.Input:Position(input)
        local owner = find(point)
        if not owner then
            return
        end
        if right then
            owner.Window:Focus()
            self:Open(owner, point, owner.Options.ContextMenu)
            return true
        end
        self.Touch = { Input = input, Point = point }
        self.Pending = task.delay(0.55, function()
            self.Pending = nil
            self.Touch = nil
            if not owner.Destroyed then
                self.App.Input:Cancel(owner)
                self:Open(owner, point, owner.Options.ContextMenu)
            end
        end)
    end, 950))
    self.Maid:Give(self.App.Input.Changed:Connect(function(input)
        if
            self.Touch
            and input == self.Touch.Input
            and (self.App.Input:Position(input) - self.Touch.Point).Magnitude > 10
        then
            self:_cancel()
        end
    end))
    self.Maid:Give(self.App.Input.Ended:Connect(function(input)
        if self.Touch and input == self.Touch.Input then
            self:_cancel()
        end
    end))
    self.Maid:Give(function()
        self:_cancel()
    end)
end
function ContextMenu:Open(owner, point, custom)
    if self.App.Modal.Active or owner.Destroyed then
        return
    end
    local entries = custom
        or {
            {
                Title = "Reset",
                Callback = function()
                    owner:Reset()
                end,
            },
            {
                Title = "Copy value",
                Callback = function()
                    local value = owner:GetValue()
                    local text = type(value) == "table" and self.App.Config:EncodeValue(value)
                        or tostring(value)
                    if self.App.Clipboard then
                        self.App:Call(self.App.Clipboard, text)
                    else
                        self.App.Modal:Show(
                            owner.Window,
                            { Title = "Copy value", Kind = "Input", Default = text, ConfirmText = "Done" }
                        )
                    end
                end,
            },
            {
                Title = owner.Disabled and "Enable" or "Disable",
                Callback = function()
                    owner:SetDisabled(not owner.Disabled)
                end,
            },
            {
                Title = "Remove",
                Danger = true,
                Callback = function()
                    owner:Destroy()
                end,
            },
        }
    self.App.Overlay:Open(owner, point, Vector2.new(190, #entries * 36 + 12), function(ctx, panel)
        Gui.padding(ctx, panel, 6)
        Gui.list(ctx, panel, 2)
        for index, entry in ipairs(entries) do
            local button = Gui.button(ctx, panel, entry.Title, {
                Size = UDim2.new(1, 0, 0, 32),
                TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = index,
            })
            Gui.padding(ctx, button, 8)
            if entry.Danger then
                button.TextColor3 = ctx.Theme.Tokens.Danger
            end
            ctx.Maid:Give(button.Activated:Connect(function()
                self.App.Overlay:Close("Selected")
                self.App:Call(entry.Callback)
            end))
        end
    end)
end
function ContextMenu:Attach(owner)
    self.Registry[owner] = true
    return function()
        self.Registry[owner] = nil
    end
end
function ContextMenu:Destroy()
    self.Maid:Destroy()
    table.clear(self.Registry)
end
return ContextMenu

end
__modules["Aurelis/Overlay/DropdownOverlay"] = function(__require)
--!nonstrict
-- One portal and one input layer for all popovers. Replacing a popover destroys its scope.
local Cleanup = __require("Aurelis/Core/Cleanup")
local Gui = __require("Aurelis/Utility/Gui")
local Math = __require("Aurelis/Utility/Math")
local UIS = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local Overlay = {}
Overlay.__index = Overlay
function Overlay.new(app)
    return setmetatable({ App = app, Active = nil }, Overlay)
end
function Overlay:Open(owner, anchor, size, build, options)
    options = options or {}
    self:Close("Replaced")
    local maid = Cleanup.new()
    local ctx =
        { App = self.App, Window = owner.Window or owner, Theme = owner.Theme or self.App.Theme, Maid = maid }
    local active = {
        Owner = owner,
        Context = ctx,
        Maid = maid,
        Options = options,
        PreviousSelection = GuiService.SelectedObject,
    }
    self.Active = active
    if options.Blocking then
        active.Dim = Gui.new(ctx, "TextButton", {
            Name = "ModalBackdrop",
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.new(),
            BackgroundTransparency = 0.45,
            ZIndex = 1,
        }, nil, self.App.Layer)
        maid:Give(active.Dim)
    end
    local viewport = self.App.Root.AbsoluteSize
    size = Vector2.new(
        math.min(size.X, math.max(1, viewport.X - 16)),
        math.min(size.Y, math.max(1, viewport.Y - 16))
    )
    local panel = Gui.new(ctx, "CanvasGroup", {
        Name = "AurelisOverlay",
        Size = UDim2.fromOffset(size.X, size.Y),
        BackgroundTransparency = 0,
        GroupTransparency = 1,
        ZIndex = 2,
        ClipsDescendants = true,
    }, { BackgroundColor3 = "SurfaceElevated" }, self.App.Layer)
    active.Panel = panel
    maid:Give(panel)
    Gui.corner(ctx, panel)
    Gui.stroke(ctx, panel, true)
    local function place()
        if self.Active ~= active then
            return
        end
        local screen = self.App.Root.AbsoluteSize
        panel.Size = UDim2.fromOffset(
            math.min(size.X, math.max(1, screen.X - 16)),
            math.min(size.Y, math.max(1, screen.Y - 16))
        )
        if options.Centered then
            panel.Position = UDim2.fromOffset(
                math.max(8, (screen.X - panel.AbsoluteSize.X) / 2),
                math.max(8, (screen.Y - panel.AbsoluteSize.Y) / 2)
            )
        else
            local point = typeof(anchor) == "Vector2" and anchor
                or anchor.AbsolutePosition + Vector2.new(0, anchor.AbsoluteSize.Y + 6)
            local placed = Math.place(
                point,
                panel.AbsoluteSize,
                screen,
                true,
                typeof(anchor) == "Instance" and anchor.AbsoluteSize.Y or 0
            )
            panel.Position = UDim2.fromOffset(placed.X, placed.Y)
        end
    end
    place()
    maid:Give(self.App.Root:GetPropertyChangedSignal("AbsoluteSize"):Connect(place))
    if typeof(anchor) == "Instance" then
        maid:Give(anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(place))
        maid:Give(anchor.Destroying:Connect(function()
            self:Close("OwnerDestroyed")
        end))
    end
    maid:Give(self.App.Input:OnBegan(function(input, processed)
        if self.Active ~= active then
            return
        end
        if input.KeyCode == Enum.KeyCode.Escape and not options.Critical then
            self:Close("Escape")
            return true
        end
        local pointer = input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        if pointer and not self.App.Input:Contains(panel, self.App.Input:Position(input)) then
            if not options.Blocking then
                self:Close("Outside")
            end
            return options.Blocking == true
        end
        if options.OnInput and options.OnInput(input, processed) then
            return true
        end
        if options.Blocking and input.KeyCode ~= Enum.KeyCode.Unknown then
            return true
        end
    end, 1000))
    local ok, err = pcall(build, ctx, panel, active)
    if not ok then
        self:Close("Error")
        error(err, 2)
    end
    self.App.Motion:Tween(panel, { GroupTransparency = 0 }, "Normal")
    self.App:_updateBlur()
    return active
end
function Overlay:Close(reason)
    local active = self.Active
    if not active then
        return
    end
    self.Active = nil
    local focused = UIS:GetFocusedTextBox()
    if focused and focused:IsDescendantOf(active.Panel) then
        focused:ReleaseFocus()
    end
    active.Maid:Destroy()
    if active.Options.OnClose then
        active.Options.OnClose(reason or "Closed")
    end
    if reason ~= "Replaced" and active.PreviousSelection and active.PreviousSelection.Parent then
        GuiService.SelectedObject = active.PreviousSelection
    end
    self.App:_updateBlur()
end
function Overlay:CloseOwner(owner)
    if self.Active and self.Active.Owner == owner then
        self:Close("OwnerClosed")
    end
end
function Overlay:Destroy()
    self:Close("Destroyed")
end
return Overlay

end
__modules["Aurelis/Overlay/Modal"] = function(__require)
--!nonstrict
local Gui = __require("Aurelis/Utility/Gui")
local Signal = __require("Aurelis/Utility/Signal")
local UIS = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local Modal = {}
Modal.__index = Modal
function Modal.new(app)
    return setmetatable({ App = app, Active = nil }, Modal)
end
function Modal:Show(window, options)
    options = options or {}
    local controller = { Result = Signal.new(), Closed = false }
    local field, confirm, focusIndex = nil, nil, 1
    local focusables = {}
    local function finish(accepted, value)
        if controller.Closed then
            return
        end
        controller.Closed = true
        controller.Result:Fire(accepted, value)
        controller.Result:Destroy()
        if accepted and options.OnConfirm then
            self.App:Call(options.OnConfirm, value)
        end
        if not accepted and options.OnCancel then
            self.App:Call(options.OnCancel)
        end
    end
    function controller:Close()
        self._service.App.Overlay:Close("Cancelled")
    end
    controller._service = self
    self.App.Overlay:Open(
        window,
        nil,
        Vector2.new(options.Width or 420, options.Kind == "Input" and 270 or 226),
        function(ctx, panel, overlay)
            self.Active = controller
            Gui.new(ctx, "UIScale", { Scale = 0.97 }, nil, panel)
            local scale = panel:FindFirstChildOfClass("UIScale")
            self.App.Motion:Tween(scale, { Scale = 1 }, "Spring")
            Gui.label(ctx, panel, options.Title or "Aurelis", {
                Position = UDim2.fromOffset(22, 20),
                Size = UDim2.new(1, -44, 0, 27),
                TextSize = 18,
                Font = Enum.Font.GothamMedium,
            })
            Gui.label(ctx, panel, options.Content or "", {
                Position = UDim2.fromOffset(22, 59),
                Size = UDim2.new(1, -44, 0, 67),
                TextWrapped = true,
                TextYAlignment = Enum.TextYAlignment.Top,
                TextSize = 12,
            }, "TextSecondary")
            local errorLabel = Gui.label(
                ctx,
                panel,
                "",
                { Position = UDim2.new(0, 22, 1, -97), Size = UDim2.new(1, -44, 0, 18), TextSize = 10 },
                "Danger"
            )
            if options.Kind == "Input" then
                field = Gui.new(ctx, "TextBox", {
                    Position = UDim2.fromOffset(22, 129),
                    Size = UDim2.new(1, -44, 0, 34),
                    Text = tostring(options.Default or ""),
                    PlaceholderText = options.Placeholder or "Enter value…",
                    ClearTextOnFocus = false,
                    BackgroundTransparency = 0,
                }, { BackgroundColor3 = "Background", TextColor3 = "TextPrimary" }, panel)
                Gui.corner(ctx, field, 7)
                Gui.stroke(ctx, field)
                Gui.padding(ctx, field, 8)
                table.insert(focusables, field)
            end
            local cancel = Gui.button(
                ctx,
                panel,
                options.CancelText or "Cancel",
                { Position = UDim2.new(1, -224, 1, -58), Size = UDim2.fromOffset(94, 36) }
            )
            table.insert(focusables, cancel)
            confirm = Gui.button(
                ctx,
                panel,
                options.ConfirmText or (options.Kind == "Destructive" and "Delete" or "Confirm"),
                {
                    Position = UDim2.new(1, -122, 1, -58),
                    Size = UDim2.fromOffset(100, 36),
                    BackgroundTransparency = 0,
