    GetValue: (self: ValueComponent<T>) -> T,
    SetValue: (self: ValueComponent<T>, value: T, silent: boolean?) -> (boolean, string?),
    SetDisabled: (self: ValueComponent<T>, disabled: boolean) -> ValueComponent<T>,
