        object.AutoButtonColor = false
        object.Selectable = true
    end
    for key, value in pairs(properties or {}) do
        object[key] = value
    end
    if tokens then
        ctx.Maid:Give(ctx.Theme:Bind(object, tokens))
    end
    object.Parent = parent
